var n=`0013-bohrach`;var a=`world-0013`;var i=`UA`;var o=`eastern-europe`;var r=4;var s=88;var l={en:`Bohrach`,ua:`Бограч`};var g={en:`A classic dish from Ukraine, featuring beef chuck, yellow onion, carrot, red bell pepper. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Україна. Основні складники: яловича лопатка, жовта цибуля, морква, червоний солодкий перець. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var d=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 10 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 10 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:10,i:[[`beef-chuck`,450,`g`],[`lard`,35,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 10 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 10 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:10,i:[[`yellow-onion`,160,`g`],[`carrot`,140,`g`],[`red-bell-pepper`,160,`g`],[`sweet-paprika`,15,`g`]]},{en:`Add the braising liquid and seasonings, cover and cook gently for about 65 minutes until the meat is tender and safely cooked.`,ua:`Додайте рідину та приправи для тушкування, накрийте кришкою й готуйте на малому вогні приблизно 65 хвилин до м’якості та повної готовності м’яса.`,t:[`braising`],m:65,i:[[`potato`,350,`g`],[`tomato`,250,`g`],[`water`,850,`ml`],[`garlic`,3,`clove`],[`bay-leaf`,1,`leaf`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`table-salt`,null,`to_taste`],[`ground-black-pepper`,null,`to_taste`],[`parsley`,15,`g`]]}];var u={slug:n,id:a,country:`UA`,region:o,servings:4,minutes:88,title:l,text:g,steps:d};export{i as country,u as default,a as id,s as minutes,o as region,r as servings,n as slug,d as steps,g as text,l as title};